int lfs_bd_cmp(lfs_t *lfs, const lfs_cache_t *pcache, lfs_cache_t *rcache, lfs_size_t hint, lfs_block_t block, lfs_off_t off, const void *buffer, lfs_size_t size) {
    const uint8_t *data = (const uint8_t *)buffer;
    if (off + size > lfs->cfg->block_size || (lfs->block_count && block >= lfs->block_count)) {
        return LFS_ERR_CORRUPT;
    }

    while (size > 0) {
        lfs_size_t diff = size;

        // Check if data is in pcache
        if (pcache && block == pcache->block && off < pcache->off + pcache->size) {
            if (off >= pcache->off) {
                diff = lfs_min(diff, pcache->size - (off - pcache->off));
                int res = memcmp(data, &pcache->buffer[off - pcache->off], diff);
                if (res != 0) {
                    return (res < 0) ? LFS_CMP_LT : LFS_CMP_GT;
                }
                data += diff;
                off += diff;
                size -= diff;
                continue;
            }
            diff = lfs_min(diff, pcache->off - off);
        }

        // Check if data is in rcache
        if (rcache && block == rcache->block && off < rcache->off + rcache->size) {
            if (off >= rcache->off) {
                diff = lfs_min(diff, rcache->size - (off - rcache->off));
                int res = memcmp(data, &rcache->buffer[off - rcache->off], diff);
                if (res != 0) {
                    return (res < 0) ? LFS_CMP_LT : LFS_CMP_GT;
                }
                data += diff;
                off += diff;
                size -= diff;
                continue;
            }
            diff = lfs_min(diff, rcache->off - off);
        }

        // Read data from block device into rcache
        if (rcache) {
            rcache->block = block;
            rcache->off = lfs_aligndown(off, lfs->cfg->read_size);
            rcache->size = lfs_min(lfs_alignup(off + diff, lfs->cfg->read_size),
                                  lfs->cfg->block_size) - rcache->off;
            int err = lfs->cfg->read(lfs->cfg, block, rcache->off, rcache->buffer, rcache->size);
            if (err) {
                return err;
            }
        } else {
            // Bypass cache and read directly
            uint8_t temp[diff];
            int err = lfs->cfg->read(lfs->cfg, block, off, temp, diff);
            if (err) {
                return err;
            }
            int res = memcmp(data, temp, diff);
            if (res != 0) {
                return (res < 0) ? LFS_CMP_LT : LFS_CMP_GT;
            }
            data += diff;
            off += diff;
            size -= diff;
            continue;
        }
    }

    return LFS_CMP_EQ;
}

