                lfs->cfg->block_size) - read_off;

            int err = lfs->cfg->read(lfs->cfg, block, read_off,
                                    rcache->buffer, read_size);
            if (err) {
                return err;
            }

            rcache->block = block;
            rcache->off = read_off;
            rcache->size = read_size;
        } else {
            // Bypass cache if no rcache available
            uint8_t temp[diff];
            int err = lfs->cfg->read(lfs->cfg, block, off, temp, diff);
            if (err) {
                return err;
            }
            int res = memcmp(data, temp, diff);
            if (res != 0) {
                return (res < 0) ? LFS_CMP_LT : LFS_CMP_GT;
            }
            data += diff;
            off += diff;
            size -= diff;
        }
    }

    return LFS_CMP_EQ;
